begin;
insert into public.site_content_blocks(page_key,block_key,label,default_text) values
('information/patch-165921.html','text-intro','Introduction','Checked 21 October 2026 new patch. These are companion-site findings, separate from official patch notes.'),
('information/patch-165921.html','text-status-title','Heading · What has been checked','What has been checked'),
('information/patch-165921.html','note-status-evidence','Info box · Patch data are not in-game verified. New Patch contains the additions below. Unchanged website ','Patch data are not in-game verified. New Patch contains the additions below. Unchanged website datasets are not automatically verified for this patch.'),
('information/patch-165921.html','text-status-scope','Text · With new level cap at 3,600, the stats calculator and My Tatari now support recorded account le','With new level cap at 3,600, the stats calculator and My Tatari now support recorded account levels 1–3,600. The Horde / Goldrush calculator remains a fixed level-500 comparison.'),
('information/patch-165921.html','text-tatari-title','Heading · Bonobean and account levels','Bonobean and account levels'),
('information/patch-165921.html','text-tatari-bonobean','Text · Bonobean, Titanape, Grangutan and Primakong are now integrated across My Tatari, the database, ','Bonobean, Titanape, Grangutan and Primakong are now integrated across My Tatari, the database, stats calculator, evolution planner, Horde guide/drafter and tierlist tools.'),
('information/patch-165921.html','text-horde-title','Heading · Horde Season 3 configuration','Horde Season 3 configuration'),
('information/patch-165921.html','text-horde-difficulties','Text · The S3 lists Difficulties 1–6. The obtained data show Difficulty 6 has twice Difficulty 4’s ene','The S3 lists Difficulties 1–6. The obtained data show Difficulty 6 has twice Difficulty 4’s enemy ATK and HP; DEF increases by a smaller amount.'),
('information/patch-165921.html','text-collectibles-title','Heading · Collectible additions','Collectible additions'),
('information/patch-165921.html','text-collectibles-accessories','Text · Original and color accessory variants are present for Zapup, Sparkit, Pandaroo, Cheerling, Lull','Original and color accessory variants are present for Zapup, Sparkit, Pandaroo, Cheerling, Lullely, Funglet, Taptail, Budboo, Cavyzap, Ringtail and Popa.'),
('information/patch-165921.html','text-collectibles-limits','Text · The records confirm additions, not their availability on a particular account or release date. ','The records confirm additions, not their availability on a particular account or release date. Cosmetic records are separate from saved Glitter ownership.'),
('information/patch-165921.html','text-events-title','Heading · Halloween and battle setup','Halloween and battle setup'),
('information/patch-165921.html','text-events-halloween','Text · Trick-or-Treat reward configuration and the strings “Trick-or-Treat Time!” and “Halloween Fun!”','Trick-or-Treat reward configuration and the strings “Trick-or-Treat Time!” and “Halloween Fun!” are present. The event dates and exact replacement schedule are not established, so the site calendar has not been rescheduled from this evidence alone.'),
('information/patch-165921.html','text-events-battles','Text · All 429 new and 404 changed battle setups are now mapped and included in the website’s battle d','All 429 new and 404 changed battle setups are now mapped and included in the website’s battle dataset. The changed setups affect 404 stages in chapters 24–29. Of the new files, 404 preserve earlier setups under new references for later chapters; 25 contain Season 3 Horde waves. Enemy level, star and ATK/DEF/HP multiplier records are unchanged. The formation planner’s Stage mode now shows the configured enemy roster, lanes and spawn sequence. This updates encounter data, not battle-simulation accuracy.'),
('information/patch-165921.html','text-chips-title','Heading · Confirmed chip updates','Confirmed chip updates'),
('information/patch-165921.html','text-chips-scope','Text · The 49 chip catalogue entries, qualities, uniqueness and allowed-wave lists are unchanged. Four','The 49 chip catalogue entries, qualities, uniqueness and allowed-wave lists are unchanged. Four numeric changes occur in linked Skill records.'),
('information/patch-165921.html','text-chips-shuffle','Text · Shuffle still grants 600 energizers and will shuffle from both the deployed and undeployed Tata','Shuffle still grants 600 energizers and will shuffle from both the deployed and undeployed Tatari pool.

Contract Employees stay deployed, and their Tatari types are now excluded from the replacement pool. Ordinary replacement units inherit the replaced slots’ grid positions and Horde levels.'),
('information/patch-165921.html','text-skill-balance-title','Heading · Tatari Horde skill changes','Tatari Horde skill changes'),
('information/patch-165921.html','text-skill-balance-method','Text · 59 displayed value changes affect 42 existing skills in 30 Tatari families. The table uses curr','59 displayed value changes affect 42 existing skills in 30 Tatari families. The table uses current source values, including helper skills and buff tooltips.'),
('information/patch-165921.html','text-mechanics-title','Heading · Other Horde mechanics and limits','Other Horde mechanics and limits'),
('information/patch-165921.html','list-mechanics-unchanged-1','List item · All eight deployment/upgrade costs, death refunds, rank stat multipliers and skill unlock index','All eight deployment/upgrade costs, death refunds, rank stat multipliers and skill unlock indexes are unchanged.'),
('information/patch-165921.html','list-mechanics-unchanged-2','List item · Energy recovery is unchanged: start at 400, initially gain 25 every 5 seconds, decrease the per','Energy recovery is unchanged: start at 400, initially gain 25 every 5 seconds, decrease the periodic gain by 5 every 90 seconds, and gain 4 per normal kill or 100 per boss kill.'),
('information/patch-165921.html','list-mechanics-unchanged-3','List item · The rank, season-rank and wave reward tables and the balance table are unchanged.','The rank, season-rank and wave reward tables and the balance table are unchanged.'),
('information/patch-165921.html','list-mechanics-unchanged-4','List item · Horde’s configured level reference remains 500. Normal account-level inputs and Supabase saves ','Horde’s configured level reference remains 500. Normal account-level inputs and Supabase saves accept 1–3,600.'),
('information/patch-165921.html','list-mechanics-unchanged-5','List item · New parameters 39 and 40 remain unknown.','New parameters 39 and 40 remain unknown.'),
('information/patch-165921.html','text-mechanics-tooltips','Text · 86 existing Horde detail entries changed, but many edits only correct labels, formatting, histo','86 existing Horde detail entries changed, but many edits only correct labels, formatting, historical comparison values or buff/nerf arrows. Those display edits must not be counted as additional combat changes. Bonobean’s new active skill illustrates why this matters: current minimum/maximum interval fields are 22/26 seconds, while its comparison metadata lists 12/16.'),
('information/patch-165921.html','text-pending-title','Heading · Still unverified','Still unverified'),
('information/patch-165921.html','list-pending-unknowns-1','List item · Goldrush weekly giftbox limit','Goldrush weekly giftbox limit'),
('information/patch-165921.html','list-pending-unknowns-2','List item · Boss Challenge merge changes','Boss Challenge merge changes'),
('information/patch-165921.html','list-pending-unknowns-3','List item · Halloween event dates and replacement timing','Halloween event dates and replacement timing'),
('information/patch-165921.html','list-pending-unknowns-4','List item · Exact match to the live server payload','Exact match to the live server payload'),
('information/patch-165921.html','list-pending-unknowns-5','List item · Meaning and consumer binding of new Horde parameters 39 (200) and 40 (5)','Meaning and consumer binding of new Horde parameters 39 (200) and 40 (5)'),
('information/patch-165921.html','list-pending-unknowns-6','List item · Selection of the official Horde parameter override and unusual Shuffle edge cases','Selection of the official Horde parameter override and unusual Shuffle edge cases')
on conflict(page_key,block_key) do nothing;
commit;
